ALTER TABLE public.organization_subscriptions ADD COLUMN seat_limit integer;
UPDATE public.organization_subscriptions s SET seat_limit=p.max_users FROM public.subscription_plans p WHERE s.plan_id=p.id;
ALTER TABLE public.organization_subscriptions ADD CONSTRAINT company_seat_limit_range CHECK (seat_limit BETWEEN 1 AND 10);
CREATE OR REPLACE FUNCTION public.org_max_users(_org uuid) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE((SELECT COALESCE(s.seat_limit,p.max_users) FROM public.organization_subscriptions s JOIN public.subscription_plans p ON p.id=s.plan_id WHERE s.organization_id=_org),0) $$;
CREATE OR REPLACE FUNCTION public.my_org_context() RETURNS TABLE(organization_id uuid, organization_name text, role text, plan_slug text, plan_name text, max_users integer, active_users integer, pending_invites integer, subscription_status text, features jsonb, permissions text[]) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH o AS(SELECT public.current_org() id) SELECT org.id,org.name,m.role,p.slug,p.name,public.org_max_users(org.id),(SELECT count(*) FROM public.organization_members WHERE organization_id=org.id AND status='active')::int,(SELECT count(*) FROM public.organization_invitations WHERE organization_id=org.id AND status='pending' AND expires_at>now())::int,s.status,CASE WHEN public.org_subscription_access(org.id) THEN COALESCE(p.features,'[]'::jsonb) ELSE '[]'::jsonb END,ARRAY(SELECT rp.permission FROM public.role_permissions rp WHERE rp.role=m.role) FROM o JOIN public.organizations org ON org.id=o.id JOIN public.organization_members m ON m.organization_id=org.id AND m.user_id=auth.uid() AND m.status='active' LEFT JOIN public.organization_subscriptions s ON s.organization_id=org.id LEFT JOIN public.subscription_plans p ON p.id=s.plan_id $$;
CREATE OR REPLACE FUNCTION public.apply_company_payment(_env text,_event text,_org uuid,_state jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid; prev jsonb; seats integer; BEGIN IF _env NOT IN ('sandbox','live') THEN RAISE EXCEPTION 'Invalid environment'; END IF; SELECT payment_states->_env INTO prev FROM public.organization_subscriptions WHERE organization_id=_org FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown organization'; END IF; INSERT INTO public.payment_events(environment,event_id) VALUES(_env,_event) ON CONFLICT DO NOTHING; IF NOT FOUND THEN RETURN; END IF; SELECT id INTO p FROM public.subscription_plans WHERE stripe_price_id=_state->>'price_id'; IF p IS NULL THEN RAISE EXCEPTION 'Unknown price'; END IF; seats:=(_state->>'seats')::integer; IF seats IS NOT NULL AND (seats<1 OR seats>10) THEN RAISE EXCEPTION 'Invalid seats'; END IF; UPDATE public.organization_subscriptions SET payment_states=jsonb_set(payment_states,ARRAY[_env],_state,true),updated_at=now() WHERE organization_id=_org; IF _env='live' THEN UPDATE public.organization_subscriptions SET plan_id=p,status=_state->>'status',stripe_subscription_id=_state->>'subscription_id',stripe_price_id=_state->>'price_id',current_period_start=(_state->>'period_start')::timestamptz,current_period_end=(_state->>'period_end')::timestamptz,paid_confirmed=COALESCE((_state->>'paid')::boolean,false),cancel_at_period_end=COALESCE((_state->>'cancel_at_period_end')::boolean,false),seat_limit=COALESCE(seats,seat_limit) WHERE organization_id=_org; END IF; END $$;
REVOKE ALL ON FUNCTION public.apply_company_payment(text,text,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_company_payment(text,text,uuid,jsonb) TO service_role;